### `frontend/src/pages/ChatPage.tsx`

```typescript
import React, { useState, useEffect, useRef } from 'react'
import {
  Box,
  VStack,
  HStack,
  Input,
  Button,
  Text,
  Avatar,
  Flex,
  useColorModeValue,
  IconButton,
  Menu,
  MenuButton,
  MenuList,
  MenuItem,
  Badge,
  Spinner,
  Textarea,
} from '@chakra-ui/react'
import { 
  IoSend, 
  IoMic, 
  IoAttach, 
  IoSettings, 
  IoEllipsisVertical 
} from 'react-icons/io5'
import { useParams } from 'react-router-dom'
import { useSelector, useDispatch } from 'react-redux'
import ReactMarkdown from 'react-markdown'
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter'
import { tomorrow } from 'react-syntax-highlighter/dist/esm/styles/prism'

import { RootState, AppDispatch } from '../store'
import { sendMessage, loadConversation } from '../store/slices/chatSlice'
import { useWebSocket } from '../hooks/useWebSocket'
import LoadingSpinner from '../components/common/LoadingSpinner'

interface Message {
  id: string
  role: 'user' | 'assistant'
  content: string
  timestamp: string
  model?: string
  processing_time?: number
}

const ChatPage: React.FC = () => {
  const { conversationId } = useParams()
  const dispatch = useDispatch<AppDispatch>()
  const [inputMessage, setInputMessage] = useState('')
  const [isRecording, setIsRecording] = useState(false)
  const messagesEndRef = useRef<HTMLDivElement>(null)

  const {
    messages,
    currentConversation,
    isLoading,
    error
  } = useSelector((state: RootState) => state.chat)

  const { user } = useSelector((state: RootState) => state.auth)

  const bg = useColorModeValue('white', 'gray.800')
  const borderColor = useColorModeValue('gray.200', 'gray.600')

  // WebSocket kapcsolat
  const { sendMessage: sendWsMessage, isConnected } = useWebSocket({
    onMessage: (data) => {
      // WebSocket üzenetek kezelése
      console.log('WebSocket message:', data)
    }
  })

  useEffect(() => {
    if (conversationId) {
      dispatch(loadConversation(conversationId))
    }
  }, [conversationId, dispatch])

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  const handleSendMessage = async () => {
    if (!inputMessage.trim()) return

    const messageData = {
      message: inputMessage,
      conversation_id: conversationId,
      models: ['gpt-4o', 'claude-3-5-sonnet-20241022'],
      temperature: 0.7
    }

    try {
      await dispatch(sendMessage(messageData)).unwrap()
      setInputMessage('')
    } catch (error) {
      console.error('Üzenet küldési hiba:', error)
    }
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  const MessageComponent: React.FC<{ message: Message }> = ({ message }) => {
    const isUser = message.role === 'user'
    const bgColor = useColorModeValue(
      isUser ? 'blue.500' : 'gray.100',
      isUser ? 'blue.600' : 'gray.700'
    )
    const textColor = useColorModeValue(
      isUser ? 'white' : 'gray.800',
      isUser ? 'white' : 'gray.100'
    )

    return (
      <Flex
        justify={isUser ? 'flex-end' : 'flex-start'}
        mb={4}
      >
        <HStack
          maxW="70%"
          align="flex-start"
          flexDirection={isUser ? 'row-reverse' : 'row'}
        >
          <Avatar
            size="sm"
            name={isUser ? user?.username : 'AI'}
            src={isUser ? user?.avatar_url : '/ai-avatar.png'}
          />
          <Box
            bg={bgColor}
            color={textColor}
            px={4}
            py={3}
            borderRadius="lg"
            borderTopRightRadius={isUser ? 'sm' : 'lg'}
            borderTopLeftRadius={isUser ? 'lg' : 'sm'}
            maxW="100%"
            wordBreak="break-word"
          >
            {isUser ? (
              <Text>{message.content}</Text>
            ) : (
              <Box>
                <ReactMarkdown
                  components={{
                    code({ node, inline, className, children, ...props }) {
                      const match = /language-(\w+)/.exec(className || '')
                      return !inline && match ? (
                        <SyntaxHighlighter
                          style={tomorrow}
                          language={match[1]}
                          PreTag="div"
                          {...props}
                        >
                          {String(children).replace(/\n$/, '')}
                        </SyntaxHighlighter>
                      ) : (
                        <code className={className} {...props}>
                          {children}
                        </code>
                      )
                    }
                  }}
                >
                  {message.content}
                </ReactMarkdown>
                {message.model && (
                  <HStack mt={2} justify="space-between">
                    <Badge size="sm" colorScheme="purple">
                      {message.model}
                    </Badge>
                    {message.processing_time && (
                      <Text fontSize="xs" opacity={0.7}>
                        {message.processing_time.toFixed(2)}s
                      </Text>
                    )}
                  </HStack>
                )}
              </Box>
            )}
          </Box>
        </HStack>
      </Flex>
    )
  }

  return (
    <Box h="calc(100vh - 140px)" display="flex" flexDirection="column">
      {/* Chat header */}
      <Flex
        p={4}
        borderBottom="1px"
        borderColor={borderColor}
        justify="space-between"
        align="center"
        bg={bg}
      >
        <VStack align="start" spacing={0}>
          <Text fontSize="lg" fontWeight="bold">
            {currentConversation?.title || 'Új beszélgetés'}
          </Text>
          <HStack>
            <Box
              w={2}
              h={2}
              borderRadius="full"
              bg={isConnected ? 'green.400' : 'red.400'}
            />
            <Text fontSize="sm" color="gray.500">
              {isConnected ? 'Kapcsolódva' : 'Kapcsolódás...'}
            </Text>
          </HStack>
        </VStack>

        <Menu>
          <MenuButton
            as={IconButton}
            icon={<IoEllipsisVertical />}
            variant="ghost"
            size="sm"
          />
          <MenuList>
            <MenuItem icon={<IoSettings />}>
              Beállítások
            </MenuItem>
          </MenuList>
        </Menu>
      </Flex>

      {/* Messages area */}
      <Box
        flex={1}
        overflowY="auto"
        p={4}
        bg={useColorModeValue('gray.50', 'gray.900')}
      >
        {isLoading && messages.length === 0 ? (
          <Flex justify="center" align="center" h="100%">
            <LoadingSpinner />
          </Flex>
        ) : (
          <VStack spacing={0} align="stretch">
            {messages.map((message) => (
              <MessageComponent key={message.id} message={message} />
            ))}
            {isLoading && (
              <Flex justify="flex-start" mb={4}>
                <HStack>
                  <Avatar size="sm" name="AI" src="/ai-avatar.png" />
                  <Box
                    bg={useColorModeValue('gray.100', 'gray.700')}
                    px={4}
                    py={3}
                    borderRadius="lg"
                    borderTopLeftRadius="sm"
                  >
                    <HStack>
                      <Spinner size="sm" />
                      <Text>AI gondolkodik...</Text>
                    </HStack>
                  </Box>
                </HStack>
              </Flex>
            )}
            <div ref={messagesEndRef} />
          </VStack>
        )}
      </Box>

      {/* Input area */}
      <Box
        p={4}
        borderTop="1px"
        borderColor={borderColor}
        bg={bg}
      >
        <HStack spacing={2}>
          <IconButton
            icon={<IoAttach />}
            variant="ghost"
            aria-label="Fájl csatolása"
            size="sm"
          />

          <Textarea
            value={inputMessage}
            onChange={(e) => setInputMessage(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder="Írj egy üzenetet..."
            resize="none"
            minH="40px"
            maxH="120px"
            flex={1}
          />

          <IconButton
            icon={isRecording ? <IoMic color="red" /> : <IoMic />}
            variant="ghost"
            aria-label="Hang felvétel"
            size="sm"
            onClick={() => setIsRecording(!isRecording)}
          />

          <Button
            leftIcon={<IoSend />}
            onClick={handleSendMessage}
            isLoading={isLoading}
            loadingText="Küldés"
            colorScheme="blue"
            size="sm"
            isDisabled={!inputMessage.trim()}
          >
            Küldés
          </Button>
        </HStack>
      </Box>

      {error && (
        <Box
          p={2}
          bg="red.100"
          borderColor="red.200"
          borderWidth={1}
          borderRadius="md"
          m={4}
        >
          <Text color="red.800" fontSize="sm">
            {error}
          </Text>
        </Box>
      )}
    </Box>
  )
}

export default ChatPage
```

### `frontend/src/services/api.ts`

```typescript
import axios, { AxiosInstance, AxiosResponse } from 'axios'
import toast from 'react-hot-toast'

const API_BASE_URL = import.meta.env.VITE_API_URL || ''

class APIClient {
  private client: AxiosInstance

  constructor() {
    this.client = axios.create({
      baseURL: `${API_BASE_URL}/api/v1`,
      headers: {
        'Content-Type': 'application/json',
      },
    })

    // Request interceptor
    this.client.interceptors.request.use(
      (config) => {
        const token = localStorage.getItem('token')
        if (token) {
          config.headers.Authorization = `Bearer ${token}`
        }
        return config
      },
      (error) => {
        return Promise.reject(error)
      }
    )

    // Response interceptor
    this.client.interceptors.response.use(
      (response) => response,
      async (error) => {
        const originalRequest = error.config

        if (error.response?.status === 401 && !originalRequest._retry) {
          originalRequest._retry = true

          try {
            const refreshToken = localStorage.getItem('refreshToken')
            if (refreshToken) {
              const response = await this.client.post('/auth/refresh', {
                refresh_token: refreshToken
              })

              const { access_token } = response.data
              localStorage.setItem('token', access_token)

              return this.client(originalRequest)
            }
          } catch (refreshError) {
            localStorage.removeItem('token')
            localStorage.removeItem('refreshToken')
            window.location.href = '/login'
            return Promise.reject(refreshError)
          }
        }

        if (error.response?.data?.detail) {
          toast.error(error.response.data.detail)
        } else {
          toast.error('Valami hiba történt')
        }

        return Promise.reject(error)
      }
    )
  }

  async get<T = any>(url: string): Promise<AxiosResponse<T>> {
    return this.client.get<T>(url)
  }

  async post<T = any>(url: string, data?: any): Promise<AxiosResponse<T>> {
    return this.client.post<T>(url, data)
  }

  async put<T = any>(url: string, data?: any): Promise<AxiosResponse<T>> {
    return this.client.put<T>(url, data)
  }

  async delete<T = any>(url: string): Promise<AxiosResponse<T>> {
    return this.client.delete<T>(url)
  }
}

const apiClient = new APIClient()

// Auth API
export const authAPI = {
  login: (username: string, password: string) =>
    apiClient.post('/auth/login', { username, password }),

  register: (userData: {
    email: string
    username: string
    password: string
    full_name?: string
  }) => apiClient.post('/auth/register', userData),

  validateToken: () => apiClient.get('/auth/validate-token'),

  refreshToken: () => {
    const refreshToken = localStorage.getItem('refreshToken')
    return apiClient.post('/auth/refresh', { refresh_token: refreshToken })
  },

  logout: () => apiClient.post('/auth/logout'),
}

// Chat API
export const chatAPI = {
  sendMessage: (data: {
    message: string
    conversation_id?: string
    models?: string[]
    temperature?: number
    max_tokens?: number
  }) => apiClient.post('/chat/send', data),

  getConversations: (limit = 50, offset = 0) =>
    apiClient.get(`/chat/conversations?limit=${limit}&offset=${offset}`),

  getConversationMessages: (conversationId: string, limit = 100, offset = 0) =>
    apiClient.get(`/chat/conversations/${conversationId}/messages?limit=${limit}&offset=${offset}`),

  createConversation: (data: {
    title?: string
    description?: string
    model_preferences?: string[]
  }) => apiClient.post('/chat/conversations', data),

  updateConversation: (conversationId: string, data: {
    title?: string
    description?: string
    model_preferences?: string[]
    is_archived?: boolean
  }) => apiClient.put(`/chat/conversations/${conversationId}`, data),

  deleteConversation: (conversationId: string) =>
    apiClient.delete(`/chat/conversations/${conversationId}`),

  getAvailableModels: () => apiClient.get('/chat/models'),

  rateMessage: (messageId: string, rating: number, feedback?: string) =>
    apiClient.post(`/chat/messages/${messageId}/rate`, { rating, feedback }),
}

export default apiClient
