import pytest
from httpx import AsyncClient
from unittest.mock import patch

from app.models.user import User


class TestOWASPSecurity:
    """OWASP Top 10 biztonsági tesztek"""

    @pytest.mark.asyncio
    async def test_sql_injection_prevention(self, test_client: AsyncClient, auth_headers: dict):
        """SQL injection védelem teszt"""
        # SQL injection kísérlet üzenetben
        malicious_message = "'; DROP TABLE users; --"

        response = await test_client.post(
            "/api/v1/chat/send",
            json={"message": malicious_message},
            headers=auth_headers
        )

        # Az alkalmazás nem crash-el, normálisan kezeli
        assert response.status_code in [200, 422, 500]

        # Felhasználók továbbra is léteznek
        user_response = await test_client.get("/api/v1/auth/me", headers=auth_headers)
        assert user_response.status_code == 200

    @pytest.mark.asyncio
    async def test_xss_prevention(self, test_client: AsyncClient, auth_headers: dict):
        """XSS védelem teszt"""
        xss_payloads = [
            "<script>alert('XSS')</script>",
            "javascript:alert('XSS')",
            "<img src=x onerror=alert('XSS')>",
            "<svg onload=alert('XSS')>"
        ]

        for payload in xss_payloads:
            # Beszélgetés címben XSS kísérlet
            response = await test_client.post(
                "/api/v1/chat/conversations",
                json={"title": payload},
                headers=auth_headers
            )

            if response.status_code == 200:
                data = response.json()
                # A címben nem szerepelhet script tag
                assert "<script>" not in data.get("title", "")
                assert "javascript:" not in data.get("title", "")

    @pytest.mark.asyncio
    async def test_csrf_protection(self, test_client: AsyncClient):
        """CSRF védelem teszt"""
        # CSRF token nélküli kérés
        response = await test_client.post("/api/v1/auth/login", data={
            "username": "testuser",
            "password": "testpassword"
        })

        # Az alkalmazás CSRF tokent nem igényel API-hoz (SPA alkalmazás)
        # De origin header ellenőrzést végez
        response_with_origin = await test_client.post(
            "/api/v1/auth/login",
            data={"username": "testuser", "password": "testpassword"},
            headers={"Origin": ""}
        )

        # CORS policy véd
        assert response_with_origin.status_code in [400, 401, 403]

    @pytest.mark.asyncio
    async def test_authentication_bypass(self, test_client: AsyncClient):
        """Autentikáció megkerülés teszt"""
        protected_endpoints = [
            "/api/v1/auth/me",
            "/api/v1/chat/send",
            "/api/v1/chat/conversations",
        ]

        for endpoint in protected_endpoints:
            # Token nélküli kérés
            response = await test_client.get(endpoint)
            assert response.status_code == 401

            # Érvénytelen token
            fake_headers = {"Authorization": "Bearer fake-token"}
            response = await test_client.get(endpoint, headers=fake_headers)
            assert response.status_code == 401

    @pytest.mark.asyncio
    async def test_rate_limiting(self, test_client: AsyncClient, test_user: User):
        """Rate limiting teszt"""
        from app.core.auth import create_access_token_for_user

