apiVersion: monitoring.coreos.com/v1
kind: PrometheusRule
metadata:
  name: jade-ai-alerts
  namespace: jade-ai-monitoring
  labels:
    app: jade-ai
    role: alert-rules
spec:
  groups:
  - name: jade-ai.rules
    rules:

    # Application Health Alerts
    - alert: JadeAIBackendDown
      expr: up{job="jade-ai-backend"} == 0
      for: 1m
      labels:
        severity: critical
        service: backend
      annotations:
        summary: "JADE AI Backend is down"
        description: "JADE AI Backend has been down for more than 1 minute"
        runbook_url: ""

    - alert: JadeAIFrontendDown
      expr: up{job="jade-ai-frontend"} == 0
      for: 1m
      labels:
        severity: critical
        service: frontend
      annotations:
        summary: "JADE AI Frontend is down"
        description: "JADE AI Frontend has been down for more than 1 minute"

    # Performance Alerts
    - alert: HighResponseTime
      expr: histogram_quantile(0.95, rate(jade_request_duration_seconds_bucket[5m])) > 2
      for: 5m
      labels:
        severity: warning
        service: backend
      annotations:
        summary: "High API response time"
        description: "95th percentile response time is {{ $value }}s"

    - alert: HighErrorRate
      expr: rate(jade_requests_total{status_code=~"5.."}[5m]) / rate(jade_requests_total[5m]) > 0.05
      for: 2m
      labels:
        severity: critical
        service: backend
      annotations:
        summary: "High error rate detected"
        description: "Error rate is {{ $value | humanizePercentage }}"

    # Resource Alerts
    - alert: HighCPUUsage
      expr: rate(container_cpu_usage_seconds_total{pod=~"jade-ai-.*"}[5m]) > 0.8
      for: 10m
      labels:
        severity: warning
      annotations:
        summary: "High CPU usage on {{ $labels.pod }}"
        description: "CPU usage is {{ $value | humanizePercentage }}"

    - alert: HighMemoryUsage
      expr: container_memory_usage_bytes{pod=~"jade-ai-.*"} / container_spec_memory_limit_bytes > 0.85
      for: 10m
      labels:
        severity: warning
      annotations:
        summary: "High memory usage on {{ $labels.pod }}"
        description: "Memory usage is {{ $value | humanizePercentage }}"

    # Database Alerts
    - alert: PostgreSQLDown
      expr: up{job="postgresql"} == 0
      for: 1m
      labels:
        severity: critical
        service: database
      annotations:
        summary: "PostgreSQL is down"
        description: "PostgreSQL database has been down for more than 1 minute"

    - alert: HighDatabaseConnections
      expr: pg_stat_database_numbackends / pg_settings_max_connections > 0.8
      for: 5m
      labels:
        severity: warning
        service: database
      annotations:
        summary: "High database connection usage"
        description: "Database connections at {{ $value | humanizePercentage }}"

    # Redis Alerts  
    - alert: RedisDown
      expr: up{job="redis"} == 0
      for: 1m
      labels:
        severity: critical
        service: cache
      annotations:
        summary: "Redis is down"
        description: "Redis cache has been down for more than 1 minute"

    - alert: RedisHighMemoryUsage
      expr: redis_memory_used_bytes / redis_memory_max_bytes > 0.9
      for: 5m
      labels:
        severity: warning
        service: cache
      annotations:
        summary: "Redis high memory usage"
        description: "Redis memory usage is {{ $value | humanizePercentage }}"

    # AI Provider Alerts
    - alert: AIProviderDown
      expr: jade_ai_requests_total{status="error"} / jade_ai_requests_total > 0.5
      for: 5m
      labels:
        severity: critical
        service: ai-provider
      annotations:
        summary: "AI Provider having issues"
        description: "AI provider {{ $labels.provider }} error rate is {{ $value | humanizePercentage }}"

    # Security Alerts
    - alert: HighFailedLogins
      expr: rate(jade_requests_total{endpoint="/api/v1/auth/login", status_code="401"}[5m]) > 10
      for: 2m
      labels:
        severity: warning
        service: security
      annotations:
        summary: "High failed login attempts"
        description: "{{ $value }} failed login attempts per second"

    - alert: UnusualTrafficPattern
      expr: rate(jade_requests_total[5m]) > 1000
      for: 5m
      labels:
        severity: warning
        service: security
      annotations:
        summary: "Unusual traffic pattern detected"
        description: "Request rate is {{ $value }} requests/second"

  - name: business.rules
    rules:

    # Business Metrics
    - alert: LowUserEngagement
      expr: rate(jade_requests_total{endpoint=~"/api/v1/chat/.*"}[1h]) < 1
      for: 30m
      labels:
        severity: warning
        service: business
      annotations:
        summary: "Low user engagement"
        description: "Chat API usage below normal levels"

    - alert: HighTokenUsage
      expr: rate(jade_ai_tokens_total[1h]) > 1000000
      for: 10m
      labels:
        severity: warning
        service: business
      annotations:
        summary: "High AI token usage"
        description: "Token usage is {{ $value }} tokens/hour"

  - name: sla.rules
    rules:

    # SLA Alerts (99.9% uptime)
