## frontend/src/App.tsx

```typescript
import React, { useEffect } from 'react'
import { Routes, Route, Navigate } from 'react-router-dom'
import { Box, Spinner, Center } from '@chakra-ui/react'
import { useSelector, useDispatch } from 'react-redux'
import { Helmet } from 'react-helmet-async'

import { RootState, AppDispatch } from './store'
import { validateToken } from './store/slices/authSlice'
import Layout from './components/Layout'
import LoginPage from './pages/LoginPage'
import RegisterPage from './pages/RegisterPage'
import DashboardPage from './pages/DashboardPage'
import ChatPage from './pages/ChatPage'
import ConversationsPage from './pages/ConversationsPage'
import ProfilePage from './pages/ProfilePage'
import SettingsPage from './pages/SettingsPage'
import LandingPage from './pages/LandingPage'
import NotFoundPage from './pages/NotFoundPage'
import LoadingSpinner from './components/common/LoadingSpinner'
import ErrorBoundary from './components/common/ErrorBoundary'

const App: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>()
  const { isAuthenticated, loading, user } = useSelector((state: RootState) => state.auth)

  useEffect(() => {
    const token = localStorage.getItem('token')
    if (token) {
      dispatch(validateToken())
    }
  }, [dispatch])

  if (loading) {
    return (
      <Center height="100vh">
        <LoadingSpinner size="xl" />
      </Center>
    )
  }

  return (
    <ErrorBoundary>
      <Helmet>
        <title>JADE AI Platform - State-of-the-Art Multi-Model AI</title>
        <meta name="description" content="Experience the future of AI with JADE AI Platform. Access multiple AI models, create intelligent conversations, and unlock unprecedented capabilities." />
        <meta name="keywords" content="AI, artificial intelligence, chat, GPT, Claude, Gemini, multi-model" />
        <meta property="og:title" content="JADE AI Platform" />
        <meta property="og:description" content="State-of-the-Art Multi-Model AI Platform" />
        <meta property="og:type" content="website" />
        <meta property="og:url" content="" />
        <link rel="canonical" href="" />
      </Helmet>

      <Routes>
        {/* Public routes */}
        <Route 
          path="/" 
          element={!isAuthenticated ? <LandingPage /> : <Navigate to="/dashboard" />} 
        />
        <Route 
          path="/login" 
          element={!isAuthenticated ? <LoginPage /> : <Navigate to="/dashboard" />} 
        />
        <Route 
          path="/register" 
          element={!isAuthenticated ? <RegisterPage /> : <Navigate to="/dashboard" />} 
        />

        {/* Protected routes */}
        <Route 
          path="/*" 
          element={
            isAuthenticated ? (
              <Layout>
                <Routes>
                  <Route path="/dashboard" element={<DashboardPage />} />
                  <Route path="/chat" element={<ChatPage />} />
                  <Route path="/chat/:conversationId" element={<ChatPage />} />
                  <Route path="/conversations" element={<ConversationsPage />} />
                  <Route path="/profile" element={<ProfilePage />} />
                  <Route path="/settings" element={<SettingsPage />} />
                  <Route path="/404" element={<NotFoundPage />} />
                  <Route path="*" element={<Navigate to="/404" />} />
                </Routes>
              </Layout>
            ) : (
              <Navigate to="/login" />
            )
          } 
        />
      </Routes>
    </ErrorBoundary>
  )
}

export default App
```

