```typescript
import { io, Socket } from 'socket.io-client'

interface WebSocketEvents {
  connect: () => void
  disconnect: () => void
  message: (data: any) => void
  error: (error: Error) => void
  typing: (data: { user_id: string; is_typing: boolean }) => void
  user_joined: (data: { user_id: string; username: string }) => void
  user_left: (data: { user_id: string; username: string }) => void
  ai_response: (data: {
    message_id: string
    content: string
    model: string
    processing_time: number
  }) => void
  connection_status: (data: { status: 'connected' | 'disconnected' | 'reconnecting' }) => void
}

class WebSocketService {
  private socket: Socket | null = null
  private reconnectAttempts = 0
  private maxReconnectAttempts = 5
  private reconnectInterval = 1000
  private isConnecting = false
  private eventListeners: Map<string, Function[]> = new Map()

  constructor() {
    this.setupSocket()
  }

  private setupSocket() {
    const wsUrl = import.meta.env.VITE_WS_URL || 'ws://localhost:8000'
    const token = localStorage.getItem('token')

    this.socket = io(wsUrl, {
      auth: {
        token: token,
      },
      transports: ['websocket'],
      timeout: 20000,
      forceNew: true,
    })

    this.setupEventListeners()
  }

  private setupEventListeners() {
    if (!this.socket) return

    this.socket.on('connect', () => {
      console.log('WebSocket connected')
      this.reconnectAttempts = 0
      this.isConnecting = false
      this.emit('connect')
      this.emit('connection_status', { status: 'connected' })
    })

    this.socket.on('disconnect', (reason) => {
      console.log('WebSocket disconnected:', reason)
      this.emit('disconnect')
      this.emit('connection_status', { status: 'disconnected' })

      if (reason === 'io server disconnect') {
        // Server disconnected, don't auto-reconnect
        return
      }

      this.handleReconnect()
    })

    this.socket.on('connect_error', (error) => {
      console.error('WebSocket connection error:', error)
      this.emit('error', error)
      this.handleReconnect()
    })

    this.socket.on('message', (data) => {
      this.emit('message', data)
    })

    this.socket.on('ai_response', (data) => {
      this.emit('ai_response', data)
    })

    this.socket.on('typing', (data) => {
      this.emit('typing', data)
    })

    this.socket.on('user_joined', (data) => {
      this.emit('user_joined', data)
    })

    this.socket.on('user_left', (data) => {
      this.emit('user_left', data)
    })

    this.socket.on('error', (error) => {
      console.error('WebSocket error:', error)
      this.emit('error', error)
    })
  }

  private handleReconnect() {
    if (this.isConnecting || this.reconnectAttempts >= this.maxReconnectAttempts) {
      return
    }

    this.isConnecting = true
    this.reconnectAttempts++
    this.emit('connection_status', { status: 'reconnecting' })

    setTimeout(() => {
      console.log(`Attempting to reconnect... (${this.reconnectAttempts}/${this.maxReconnectAttempts})`)
      this.setupSocket()
    }, this.reconnectInterval * this.reconnectAttempts)
  }

  public connect() {
    if (this.socket?.connected) {
      return
    }

    this.setupSocket()
  }

  public disconnect() {
    if (this.socket) {
      this.socket.disconnect()
      this.socket = null
    }
    this.eventListeners.clear()
  }

  public sendMessage(event: string, data?: any) {
    if (this.socket?.connected) {
      this.socket.emit(event, data)
    } else {
      console.warn('WebSocket not connected. Message not sent:', event, data)
    }
  }

  public sendChatMessage(message: string, conversationId?: string) {
    this.sendMessage('chat_message', {
      content: message,
      conversation_id: conversationId,
      timestamp: new Date().toISOString(),
    })
  }

  public sendTyping(isTyping: boolean) {
    this.sendMessage('typing', {
      is_typing: isTyping,
      timestamp: new Date().toISOString(),
    })
  }

  public joinConversation(conversationId: string) {
    this.sendMessage('join_conversation', {
      conversation_id: conversationId,
    })
  }

  public leaveConversation(conversationId: string) {
    this.sendMessage('leave_conversation', {
      conversation_id: conversationId,
    })
  }

  public on<K extends keyof WebSocketEvents>(event: K, callback: WebSocketEvents[K]) {
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, [])
    }
    this.eventListeners.get(event)!.push(callback)
  }

  public off<K extends keyof WebSocketEvents>(event: K, callback: WebSocketEvents[K]) {
    const listeners = this.eventListeners.get(event)
    if (listeners) {
      const index = listeners.indexOf(callback)
      if (index > -1) {
        listeners.splice(index, 1)
      }
    }
  }

  private emit(event: string, data?: any) {
    const listeners = this.eventListeners.get(event)
    if (listeners) {
      listeners.forEach(callback => {
        try {
          callback(data)
        } catch (error) {
          console.error('Error in WebSocket event listener:', error)
        }
      })
    }
  }

  public get isConnected(): boolean {
    return this.socket?.connected || false
  }

  public get connectionState(): 'connected' | 'disconnected' | 'connecting' {
    if (this.socket?.connected) return 'connected'
    if (this.isConnecting) return 'connecting'
    return 'disconnected'
  }
}

// Singleton instance
export const webSocketService = new WebSocketService()

// React hook for WebSocket
export const useWebSocket = (options?: {
  onConnect?: () => void
  onDisconnect?: () => void
  onMessage?: (data: any) => void
  onError?: (error: Error) => void
  onTyping?: (data: { user_id: string; is_typing: boolean }) => void
  onAIResponse?: (data: any) => void
  onConnectionStatus?: (status: 'connected' | 'disconnected' | 'reconnecting') => void
}) => {
  const { 
    onConnect, 
    onDisconnect, 
    onMessage, 
    onError, 
    onTyping, 
    onAIResponse,
    onConnectionStatus 
  } = options || {}

  React.useEffect(() => {
    if (onConnect) webSocketService.on('connect', onConnect)
    if (onDisconnect) webSocketService.on('disconnect', onDisconnect)
    if (onMessage) webSocketService.on('message', onMessage)
    if (onError) webSocketService.on('error', onError)
    if (onTyping) webSocketService.on('typing', onTyping)
    if (onAIResponse) webSocketService.on('ai_response', onAIResponse)
    if (onConnectionStatus) webSocketService.on('connection_status', onConnectionStatus)

    return () => {
      if (onConnect) webSocketService.off('connect', onConnect)
      if (onDisconnect) webSocketService.off('disconnect', onDisconnect)
      if (onMessage) webSocketService.off('message', onMessage)
      if (onError) webSocketService.off('error', onError)
      if (onTyping) webSocketService.off('typing', onTyping)
      if (onAIResponse) webSocketService.off('ai_response', onAIResponse)
      if (onConnectionStatus) webSocketService.off('connection_status', onConnectionStatus)
    }
  }, [onConnect, onDisconnect, onMessage, onError, onTyping, onAIResponse, onConnectionStatus])

  return {
    isConnected: webSocketService.isConnected,
    connectionState: webSocketService.connectionState,
    sendMessage: webSocketService.sendMessage.bind(webSocketService),
    sendChatMessage: webSocketService.sendChatMessage.bind(webSocketService),
