const chatSlice = createSlice({
  name: 'chat',
  initialState,
  reducers: {
    clearError: (state) => {
      state.error = null
    },
    setTyping: (state, action: PayloadAction<boolean>) => {
      state.isTyping = action.payload
    },
    addMessage: (state, action: PayloadAction<Message>) => {
      state.messages.push(action.payload)
    },
    updateMessage: (state, action: PayloadAction<{ id: string; updates: Partial<Message> }>) => {
      const messageIndex = state.messages.findIndex(msg => msg.id === action.payload.id)
      if (messageIndex !== -1) {
        state.messages[messageIndex] = { ...state.messages[messageIndex], ...action.payload.updates }
      }
    },
    setSelectedModels: (state, action: PayloadAction<string[]>) => {
      state.selectedModels = action.payload
    },
    setTemperature: (state, action: PayloadAction<number>) => {
      state.temperature = action.payload
    },
    setMaxTokens: (state, action: PayloadAction<number | undefined>) => {
      state.maxTokens = action.payload
    },
    clearMessages: (state) => {
      state.messages = []
      state.currentConversation = null
    },
    setCurrentConversation: (state, action: PayloadAction<Conversation | null>) => {
      state.currentConversation = action.payload
    },
  },
  extraReducers: (builder) => {
    builder
      // Send Message
      .addCase(sendMessage.pending, (state) => {
        state.isLoading = true
        state.error = null
      })
      .addCase(sendMessage.fulfilled, (state, action) => {
        state.isLoading = false
        state.currentConversation = action.payload.conversation_id ? {
          id: action.payload.conversation_id,
          title: state.currentConversation?.title,
          description: state.currentConversation?.description,
          model_preferences: state.selectedModels,
          temperature: state.temperature.toString(),
          max_tokens: state.maxTokens,
          is_active: true,
          is_archived: false,
          message_count: state.messages.length + 1,
          created_at: state.currentConversation?.created_at || new Date().toISOString(),
          updated_at: new Date().toISOString(),
        } : state.currentConversation
        state.messages.push(action.payload.message)
      })
      .addCase(sendMessage.rejected, (state, action) => {
        state.isLoading = false
        state.error = action.payload as string
      })

      // Load Conversations
      .addCase(loadConversations.fulfilled, (state, action) => {
        state.conversations = action.payload
      })
      .addCase(loadConversations.rejected, (state, action) => {
        state.error = action.payload as string
      })

      // Load Conversation
      .addCase(loadConversation.fulfilled, (state, action) => {
        state.messages = action.payload.messages
        const conversation = state.conversations.find(conv => conv.id === action.payload.conversationId)
        if (conversation) {
          state.currentConversation = conversation
        }
      })
      .addCase(loadConversation.rejected, (state, action) => {
        state.error = action.payload as string
      })

      // Create Conversation
      .addCase(createConversation.fulfilled, (state, action) => {
        state.conversations.unshift(action.payload)
        state.currentConversation = action.payload
      })
      .addCase(createConversation.rejected, (state, action) => {
        state.error = action.payload as string
      })

      // Load Available Models
      .addCase(loadAvailableModels.fulfilled, (state, action) => {
        state.availableModels = action.payload.models
        state.providerStatus = action.payload.provider_status
      })
      .addCase(loadAvailableModels.rejected, (state, action) => {
        state.error = action.payload as string
      })

      // Rate Message
      .addCase(rateMessage.fulfilled, (state, action) => {
        const messageIndex = state.messages.findIndex(msg => msg.id === action.payload.messageId)
        if (messageIndex !== -1) {
          state.messages[messageIndex].rating = action.payload.rating
          state.messages[messageIndex].feedback = action.payload.feedback
        }
      })
  },
})

export const {
  clearError,
  setTyping,
  addMessage,
  updateMessage,
  setSelectedModels,
  setTemperature,
  setMaxTokens,
  clearMessages,
  setCurrentConversation,
} = chatSlice.actions

export default chatSlice.reducer
