    },
    toggleConversationSelection: (state, action: PayloadAction<string>) => {
      const conversationId = action.payload
      const index = state.selectedConversations.indexOf(conversationId)
      if (index >= 0) {
        state.selectedConversations.splice(index, 1)
      } else {
        state.selectedConversations.push(conversationId)
      }
    },
    clearSelection: (state) => {
      state.selectedConversations = []
    },
    selectAll: (state) => {
      state.selectedConversations = state.filteredConversations.map(conv => conv.id)
    },
    clearError: (state) => {
      state.error = null
    },
  },
  extraReducers: (builder) => {
    builder
      // Fetch Conversations
      .addCase(fetchConversations.pending, (state) => {
        state.loading = true
        state.error = null
      })
      .addCase(fetchConversations.fulfilled, (state, action) => {
        state.loading = false
        state.conversations = action.payload.conversations
        state.pagination = action.payload.pagination
        state.filteredConversations = filterAndSortConversations(state)
      })
      .addCase(fetchConversations.rejected, (state, action) => {
        state.loading = false
        state.error = action.payload as string
      })

      // Delete Conversation
      .addCase(deleteConversation.fulfilled, (state, action) => {
        state.conversations = state.conversations.filter(conv => conv.id !== action.payload)
        state.filteredConversations = filterAndSortConversations(state)
      })
      .addCase(deleteConversation.rejected, (state, action) => {
        state.error = action.payload as string
      })

      // Archive Conversation
      .addCase(archiveConversation.fulfilled, (state, action) => {
        const index = state.conversations.findIndex(conv => conv.id === action.payload.id)
        if (index >= 0) {
          state.conversations[index] = action.payload
        }
        state.filteredConversations = filterAndSortConversations(state)
      })
      .addCase(archiveConversation.rejected, (state, action) => {
        state.error = action.payload as string
      })

      // Update Conversation
      .addCase(updateConversation.fulfilled, (state, action) => {
        const index = state.conversations.findIndex(conv => conv.id === action.payload.id)
        if (index >= 0) {
          state.conversations[index] = action.payload
        }
        state.filteredConversations = filterAndSortConversations(state)
      })
      .addCase(updateConversation.rejected, (state, action) => {
        state.error = action.payload as string
      })
  },
})

// Helper function for filtering and sorting
function filterAndSortConversations(state: ConversationState): Conversation[] {
  let filtered = [...state.conversations]

  // Apply search filter
  if (state.searchQuery) {
    const query = state.searchQuery.toLowerCase()
    filtered = filtered.filter(conv => 
      conv.title?.toLowerCase().includes(query) ||
      conv.description?.toLowerCase().includes(query)
    )
  }

  // Apply status filter
  if (state.filterBy === 'active') {
    filtered = filtered.filter(conv => conv.is_active && !conv.is_archived)
  } else if (state.filterBy === 'archived') {
    filtered = filtered.filter(conv => conv.is_archived)
  }

  // Apply sorting
  filtered.sort((a, b) => {
    let aValue: any, bValue: any

    switch (state.sortBy) {
      case 'title':
        aValue = a.title || ''
        bValue = b.title || ''
        break
      case 'created':
        aValue = new Date(a.created_at).getTime()
        bValue = new Date(b.created_at).getTime()
        break
      case 'updated':
      default:
        aValue = new Date(a.updated_at).getTime()
        bValue = new Date(b.updated_at).getTime()
        break
    }

    if (state.sortOrder === 'asc') {
      return aValue > bValue ? 1 : -1
    } else {
      return aValue < bValue ? 1 : -1
    }
  })

  return filtered
}

export const {
  setSearchQuery,
  setFilter,
  setSortBy,
  setSortOrder,
  toggleConversationSelection,
  clearSelection,
  selectAll,
  clearError,
} = conversationSlice.actions

export default conversationSlice.reducer
