import { io, Socket } from 'socket.io-client'
import { store } from '../store'
import { setConnectionStatus, addNotification } from '../store/slices/uiSlice'
import { addMessage, setTyping } from '../store/slices/chatSlice'

class WebSocketService {
  private socket: Socket | null = null
  private reconnectAttempts = 0
  private maxReconnectAttempts = 5
  private reconnectDelay = 1000

  connect(token?: string) {
    const WS_URL = import.meta.env.VITE_WS_URL || 'ws://localhost:8000'

    this.socket = io(WS_URL, {
      auth: {
        token: token || localStorage.getItem('token')
      },
      transports: ['websocket'],
      upgrade: false,
    })

    this.setupEventListeners()
  }

  private setupEventListeners() {
    if (!this.socket) return

    this.socket.on('connect', () => {
      console.log('WebSocket connected')
      store.dispatch(setConnectionStatus('connected'))
      this.reconnectAttempts = 0

      store.dispatch(addNotification({
        type: 'success',
        title: 'Connected',
        message: 'Real-time chat is now active',
      }))
    })

    this.socket.on('disconnect', (reason) => {
      console.log('WebSocket disconnected:', reason)
      store.dispatch(setConnectionStatus('disconnected'))

      if (reason === 'io server disconnect') {
        // Server initiated disconnect, don't reconnect
        return
      }

      // Attempt to reconnect
      this.attemptReconnect()
    })

    this.socket.on('connect_error', (error) => {
      console.error('WebSocket connection error:', error)
      store.dispatch(setConnectionStatus('disconnected'))
      this.attemptReconnect()
    })

    // Chat-related events
    this.socket.on('message_received', (data) => {
      store.dispatch(addMessage(data.message))
    })

    this.socket.on('user_typing', (data) => {
      store.dispatch(setTyping(data.isTyping))
    })

    this.socket.on('conversation_updated', (data) => {
      // Handle conversation updates
      console.log('Conversation updated:', data)
    })

    // System events
    this.socket.on('system_notification', (data) => {
      store.dispatch(addNotification({
        type: data.type || 'info',
        title: data.title || 'System Notification',
        message: data.message,
      }))
    })

    this.socket.on('maintenance_mode', (data) => {
      store.dispatch(addNotification({
        type: 'warning',
        title: 'Maintenance Mode',
        message: `System will be unavailable from ${data.start_time} to ${data.end_time}`,
      }))
    })
  }

  private attemptReconnect() {
    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      store.dispatch(addNotification({
        type: 'error',
        title: 'Connection Failed',
        message: 'Unable to connect to real-time chat. Please refresh the page.',
      }))
      return
    }

    this.reconnectAttempts++
    store.dispatch(setConnectionStatus('connecting'))

    setTimeout(() => {
      this.socket?.connect()
    }, this.reconnectDelay * this.reconnectAttempts)
  }

  // Chat methods
  sendMessage(data: {
    message: string
    conversation_id?: string
    models?: string[]
  }) {
    if (this.socket?.connected) {
      this.socket.emit('send_message', data)
    }
  }

  startTyping(conversationId?: string) {
    if (this.socket?.connected) {
      this.socket.emit('start_typing', { conversation_id: conversationId })
    }
  }

  stopTyping(conversationId?: string) {
    if (this.socket?.connected) {
      this.socket.emit('stop_typing', { conversation_id: conversationId })
    }
  }

  joinConversation(conversationId: string) {
    if (this.socket?.connected) {
      this.socket.emit('join_conversation', { conversation_id: conversationId })
    }
  }

  leaveConversation(conversationId: string) {
    if (this.socket?.connected) {
      this.socket.emit('leave_conversation', { conversation_id: conversationId })
    }
  }

  // Utility methods
  isConnected(): boolean {
    return this.socket?.connected || false
  }

  disconnect() {
    if (this.socket) {
      this.socket.disconnect()
      this.socket = null
    }
    store.dispatch(setConnectionStatus('disconnected'))
  }

  // Heartbeat to keep connection alive
  private startHeartbeat() {
    setInterval(() => {
      if (this.socket?.connected) {
        this.socket.emit('ping')
      }
    }, 30000) // 30 seconds
  }
}

// Singleton instance
export const wsService = new WebSocketService()

export default wsService
