                <Box key={notification.id}>
                  <HStack
                    p={3}
                    spacing={3}
                    bg={notification.read ? 'transparent' : 'blue.50'}
                    _dark={{
                      bg: notification.read ? 'transparent' : 'blue.900'
                    }}
