} from 'react-icons/fi'
import { useSelector, useDispatch } from 'react-redux'
import { useNavigate, useParams } from 'react-router-dom'
import { formatDistanceToNow } from 'date-fns'

import { RootState } from '../store'
import {
  fetchConversations,
  deleteConversation,
  archiveConversation,
  setSearchQuery,
} from '../store/slices/conversationSlice'

interface ConversationListProps {
  onClose?: () => void
}

const ConversationList: React.FC<ConversationListProps> = ({ onClose }) => {
  const dispatch = useDispatch()
  const navigate = useNavigate()
  const { conversationId } = useParams()

  const { filteredConversations, loading, searchQuery } = useSelector(
    (state: RootState) => state.conversations
  )

  const hoverBg = useColorModeValue('gray.50', 'gray.800')
  const activeBg = useColorModeValue('brand.50', 'brand.900')
  const borderColor = useColorModeValue('gray.200', 'gray.600')

  useEffect(() => {
    dispatch(fetchConversations())
  }, [dispatch])

  const handleConversationClick = (id: string) => {
    navigate(`/chat/${id}`)
    onClose?.()
  }

  const handleDeleteConversation = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation()
    if (window.confirm('Are you sure you want to delete this conversation?')) {
      try {
        await dispatch(deleteConversation(id))
        if (conversationId === id) {
          navigate('/chat')
        }
      } catch (error) {
        console.error('Failed to delete conversation:', error)
      }
    }
  }

  const handleArchiveConversation = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation()
    try {
      await dispatch(archiveConversation(id))
    } catch (error) {
      console.error('Failed to archive conversation:', error)
    }
  }

  const handleSearch = (query: string) => {
    dispatch(setSearchQuery(query))
  }

  if (loading) {
    return (
      <VStack spacing={2} p={4}>
        {Array.from({ length: 5 }).map((_, i) => (
          <Skeleton key={i} height="60px" w="full" borderRadius="md" />
        ))}
      </VStack>
    )
  }

  if (filteredConversations.length === 0) {
    return (
      <Box p={4} textAlign="center">
        <Text color="gray.500" fontSize="sm">
          {searchQuery ? 'No conversations found' : 'No conversations yet'}
        </Text>
        {searchQuery && (
          <Text color="gray.400" fontSize="xs" mt={1}>
            Try adjusting your search terms
          </Text>
        )}
      </Box>
    )
  }

  return (
    <VStack spacing={0} align="stretch">
      {filteredConversations.map((conversation) => (
        <Box
          key={conversation.id}
          className="conversation-item"
          p={3}
          cursor="pointer"
          bg={conversationId === conversation.id ? activeBg : 'transparent'}
          borderRight={conversationId === conversation.id ? '3px solid' : 'none'}
          borderRightColor="brand.500"
          _hover={{ bg: hoverBg }}
          onClick={() => handleConversationClick(conversation.id)}
          transition="all 0.2s"
        >
          <HStack spacing={3} align="start">
            <Box
              w="8px"
              h="8px"
              borderRadius="full"
              bg={conversation.is_active ? 'green.400' : 'gray.400'}
              mt={2}
              flexShrink={0}
            />

            <VStack align="start" spacing={1} flex={1} minW={0}>
              <HStack justify="space-between" w="full">
                <Text
                  fontSize="sm"
                  fontWeight="medium"
                  noOfLines={1}
                  flex={1}
