                <Menu>
                  <MenuButton
                    as={IconButton}
                    aria-label="Conversation options"
                    icon={<FiMoreVertical />}
                    size="xs"
                    variant="ghost"
                    onClick={(e) => e.stopPropagation()}
                  />
                  <MenuList>
                    <MenuItem icon={<FiEdit2 />}>
                      Edit
                    </MenuItem>
                    <MenuItem 
                      icon={<FiShare2 />}
                      onClick={(e) => e.stopPropagation()}
                    >
                      Share
                    </MenuItem>
                    <MenuItem 
                      icon={<FiArchive />}
                      onClick={(e) => handleArchiveConversation(conversation.id, e)}
                    >
                      Archive
                    </MenuItem>
                    <MenuItem 
                      icon={<FiTrash2 />}
                      color="red.500"
                      onClick={(e) => handleDeleteConversation(conversation.id, e)}
                    >
                      Delete
                    </MenuItem>
                  </MenuList>
                </Menu>
              </HStack>

              <HStack spacing={2} w="full">
                <HStack spacing={1} flex={1}>
                  <FiMessageSquare size="12px" />
                  <Text fontSize="xs" color="gray.500">
                    {conversation.message_count} messages
                  </Text>
                </HStack>

                {conversation.model_preferences.length > 0 && (
                  <Badge size="xs" colorScheme="purple">
                    {conversation.model_preferences[0]}
