              </HStack>

              <Text fontSize="xs" color="gray.500">
                {formatDistanceToNow(new Date(conversation.updated_at), { 
                  addSuffix: true 
                })}
              </Text>
            </VStack>
          </HStack>
        </Box>
      ))}
    </VStack>
  )
}

