import { useEffect, useCallback } from 'react'
import { useSelector, useDispatch } from 'react-redux'
import { RootState } from '../store'
import { setConnectionStatus } from '../store/slices/uiSlice'
import wsService from '../services/websocket'

interface UseWebSocketOptions {
  autoConnect?: boolean
  onMessage?: (data: any) => void
  onConnect?: () => void
  onDisconnect?: () => void
  onError?: (error: any) => void
}

export const useWebSocket = (options: UseWebSocketOptions = {}) => {
  const {
    autoConnect = true,
    onMessage,
    onConnect,
    onDisconnect,
    onError
  } = options

  const dispatch = useDispatch()
  const { isAuthenticated } = useSelector((state: RootState) => state.auth)
  const { connectionStatus } = useSelector((state: RootState) => state.ui)

  useEffect(() => {
    if (isAuthenticated && autoConnect) {
      const token = localStorage.getItem('token')
      if (token) {
        wsService.connect(token)
      }
    }

    return () => {
      if (!isAuthenticated) {
        wsService.disconnect()
      }
    }
  }, [isAuthenticated, autoConnect])

  const sendMessage = useCallback((data: {
    message: string
    conversation_id?: string
    models?: string[]
  }) => {
    wsService.sendMessage(data)
  }, [])

  const startTyping = useCallback((conversationId?: string) => {
    wsService.startTyping(conversationId)
  }, [])

  const stopTyping = useCallback((conversationId?: string) => {
    wsService.stopTyping(conversationId)
  }, [])

  const joinConversation = useCallback((conversationId: string) => {
    wsService.joinConversation(conversationId)
  }, [])

  const leaveConversation = useCallback((conversationId: string) => {
    wsService.leaveConversation(conversationId)
  }, [])

  const isConnected = wsService.isConnected()

  return {
    isConnected,
    connectionStatus,
    sendMessage,
    startTyping,
    stopTyping,
    joinConversation,
    leaveConversation,
  }
}

export default useWebSocket
