```typescript
import React, { useState } from 'react'
import {
  Box,
  VStack,
  HStack,
  Heading,
  Text,
  Button,
  Input,
  FormControl,
  FormLabel,
  FormErrorMessage,
  Link,
  Divider,
  Alert,
  AlertIcon,
  useColorModeValue,
  Container,
  Card,
  CardBody,
} from '@chakra-ui/react'
import { useForm } from 'react-hook-form'
import { useDispatch, useSelector } from 'react-redux'
import { Link as RouterLink, useNavigate } from 'react-router-dom'
import { Helmet } from 'react-helmet-async'

import { RootState, AppDispatch } from '../store'
import { loginUser, clearError } from '../store/slices/authSlice'

interface LoginFormData {
  username: string
  password: string
}

const LoginPage: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>()
  const navigate = useNavigate()
  const { loading, error } = useSelector((state: RootState) => state.auth)

  const bg = useColorModeValue('gray.50', 'gray.900')
  const cardBg = useColorModeValue('white', 'gray.800')

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<LoginFormData>()

  React.useEffect(() => {
    dispatch(clearError())
  }, [dispatch])

  const onSubmit = async (data: LoginFormData) => {
    try {
      await dispatch(loginUser(data)).unwrap()
      navigate('/dashboard')
    } catch (error) {
      console.error('Login failed:', error)
    }
  }

  return (
    <>
      <Helmet>
        <title>Sign In - JADE AI Platform</title>
        <meta name="description" content="Sign in to your JADE AI account to access state-of-the-art multi-model AI capabilities." />
      </Helmet>

      <Box bg={bg} minH="100vh" py={12}>
        <Container maxW="lg">
          <VStack spacing={8}>
            {/* Header */}
            <VStack spacing={4} textAlign="center">
              <Heading
                size="xl"
                bgGradient="linear(to-r, brand.400, purple.400)"
                bgClip="text"
              >
                JADE AI
              </Heading>
              <VStack spacing={2}>
                <Heading size="lg">Welcome back</Heading>
                <Text color="gray.600">
                  Sign in to your account to continue
                </Text>
              </VStack>
            </VStack>

            {/* Login Form */}
            <Card w="full" maxW="md" bg={cardBg} shadow="xl">
              <CardBody p={8}>
                <form onSubmit={handleSubmit(onSubmit)}>
                  <VStack spacing={6}>
                    {error && (
                      <Alert status="error" borderRadius="md">
                        <AlertIcon />
                        {error}
                      </Alert>
                    )}

                    <FormControl isInvalid={!!errors.username}>
                      <FormLabel>Email or Username</FormLabel>
                      <Input
                        {...register('username', {
                          required: 'Email or username is required',
                        })}
                        placeholder="Enter your email or username"
                        size="lg"
                      />
                      <FormErrorMessage>
                        {errors.username?.message}
                      </FormErrorMessage>
                    </FormControl>

                    <FormControl isInvalid={!!errors.password}>
                      <FormLabel>Password</FormLabel>
                      <Input
                        {...register('password', {
                          required: 'Password is required',
                        })}
                        type="password"
                        placeholder="Enter your password"
                        size="lg"
                      />
                      <FormErrorMessage>
                        {errors.password?.message}
                      </FormErrorMessage>
                    </FormControl>

                    <Button
                      type="submit"
                      colorScheme="brand"
                      size="lg"
                      w="full"
                      isLoading={loading}
                      loadingText="Signing in..."
                    >
                      Sign In
                    </Button>

                    <HStack justify="center" w="full">
                      <Text fontSize="sm" color="gray.600">
                        Don't have an account?
                      </Text>
                      <Link
                        as={RouterLink}
                        to="/register"
                        color="brand.500"
                        fontWeight="medium"
                        fontSize="sm"
                      >
                        Sign up
                      </Link>
                    </HStack>

                    <Divider />

                    <VStack spacing={3} w="full">
                      <Link
                        color="brand.500"
                        fontSize="sm"
                        fontWeight="medium"
                      >
                        Forgot password?
                      </Link>

                      <Text fontSize="xs" color="gray.500" textAlign="center">
                        By signing in, you agree to our{' '}
                        <Link color="brand.500">Terms of Service</Link> and{' '}
                        <Link color="brand.500">Privacy Policy</Link>
                      </Text>
                    </VStack>
                  </VStack>
                </form>
              </CardBody>
            </Card>

            {/* Demo Access */}
            <Card w="full" maxW="md" bg={cardBg} borderColor="brand.200">
              <CardBody p={6}>
                <VStack spacing={4}>
                  <Text fontSize="sm" fontWeight="medium" color="brand.600">
                    Try JADE AI Demo
                  </Text>
                  <Text fontSize="xs" color="gray.600" textAlign="center">
                    Experience our platform with a limited demo account
                  </Text>
                  <Button
                    variant="outline"
                    colorScheme="brand"
                    size="sm"
                    w="full"
                    onClick={() => {
                      // Demo login logic
                      dispatch(loginUser({
                        username: 'demo@jade-ai.com',
                        password: 'demo123'
                      }))
                    }}
                  >
                    Access Demo
                  </Button>
                </VStack>
              </CardBody>
            </Card>
          </VStack>
        </Container>
      </Box>
    </>
  )
}

export default LoginPage
```
